&__view-toggle {

function addTask(title: string) {
  const defaultStatus = statuses.value.find(
    s => s.list_id === selectedListId.value && s.category === 'TODO',
  )
  tasks.value.push({
    id: `task-${Date.now()}`,
    list_id: selectedListId.value,
    status_id: defaultStatus?.id || '',
    title,
    scheduled_date: null,
    sort_order: filteredTasks.value.length,
  })
}

input.new_string:
function addTask(title: string) {
  const defaultStatus = statuses.value.find(
    s => s.list_id === selectedListId.value && s.category === 'TODO',
  )
  tasks.value = [...tasks.value, {
    id: `task-${Date.now()}`,
    list_id: selectedListId.value,
    status_id: defaultStatus?.id || '',
    title,
    scheduled_date: null,
    sort_order: filteredTasks.value.length,
  }]
}

input.old_string:
function scheduleTask(taskId: string, date: string) {
  const task = tasks.value.find(t => t.id === taskId)
  if (task) task.scheduled_date = date
}

input.new_string:
function scheduleTask(taskId: string, date: string) {
  tasks.value = tasks.value.map(t =>
    t.id === taskId ? { ...t, scheduled_date: date } : t,
  )
}

input.old_string:
function completeTask(taskId: string) {
  const task = tasks.value.find(t => t.id === taskId)
  if (!task) return
  const currentStatus = statuses.value.find(s => s.id === task.status_id)
  const targetCategory = currentStatus?.category === 'DONE' ? 'TODO' : 'DONE'
  const newStatus = statuses.value.find(
    s => s.list_id === task.list_id && s.category === targetCategory,
  )
  if (newStatus) task.status_id = newStatus.id
}

input.new_string:
function completeTask(taskId: string) {
  const task = tasks.value.find(t => t.id === taskId)
  if (!task) return
  const currentStatus = statuses.value.find(s => s.id === task.status_id)
  const targetCategory = currentStatus?.category === 'DONE' ? 'TODO' : 'DONE'
  const newStatus = statuses.value.find(
    s => s.list_id === task.list_id && s.category === targetCategory,
  )
  if (!newStatus) return
  tasks.value = tasks.value.map(t =>
    t.id === taskId ? { ...t, status_id: newStatus.id } : t,
  )
}
